#include <iostream>

int compute(int n) {
    static int count = 0;
    count++;
    if (n <= 0) return count;
    return compute(n - 1);
}

int main() {
    std::cout << compute(3) << " ";
    std::cout << compute(2) << std::endl;
}

#include <iostream>

class Base {
public:
    void show() { std::cout << "Base "; }
};

class Derived : public Base {
public:
    void show() { std::cout << "Derived "; }
};

int main() {
    Base* ptr = new Derived();
    ptr->show();
    Derived* d = (Derived*)ptr;
    d->show();
    delete ptr;
}

